How It Works: Function Calling
Modern LLMs support function calling natively:

Tool Definition: Describe available tools with name, description, and parameter schema
LLM Decision: The model decides when and which tool to use
Execution: The tool runs server-side with the LLM-chosen parameters
Integration: Results are fed back to the LLM for final response generation

tools = [
    {
        "type": "function",
        "function": {
            "name": "search_web",
            "description": "Search the web for current information",
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {"type": "string", "description": "Search query"}
                },
                "required": ["query"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "execute_python",
            "description": "Execute Python code and return the output",
            "parameters": {
                "type": "object",
                "properties": {
                    "code": {"type": "string", "description": "Python code to execute"}
                },
                "required": ["code"]
            }
        }
    }
]

Implementation
class ReActAgent:
    def __init__(self, llm, tools):
        self.llm = llm
        self.tools = {tool.name: tool for tool in tools}
        self.system_prompt = """You are a helpful assistant. 
        For each step, output:
        Thought: &lt;your reasoning&gt;
        Action: &lt;tool_name&gt;(parameters)

        When done, use: Action: finish(answer)"""

    def run(self, question, max_steps=10):
        history = [f"Question: {question}"]

        for step in range(max_steps):
            response = self.llm.generate(self.system_prompt, history)
            thought, action = self.parse(response)
            history.append(f"Thought {step+1}: {thought}")

            if action.name == "finish":
                return action.args

            observation = self.tools[action.name].execute(action.args)
            history.append(f"Action {step+1}: {action}")
            history.append(f"Observation {step+1}: {observation}")

        return "Max steps reached without a final answer."

Why It Works
The magic lies in role separation: the generator focuses on producing content, while the critic focuses on finding flaws. This separation of concerns mirrors real-world software engineering practices like code review.
class ReflectionAgent:
    def __init__(self, model="llama3-70b"):
        self.generator_prompt = "You are a Python programmer. Write clean, production-quality code."
        self.critic_prompt = "You are a senior engineer like Andrej Karpathy. Review this code critically."

    def run(self, task, max_iterations=3):
        output = self.generate(task)
        for i in range(max_iterations):
            critique = self.reflect(output)
            if self.is_satisfied(critique):
                break
            output = self.refine(output, critique)
        return output
